#pragma once
#include <cstdint>
#include <utility>

/// Data-dependency-width microbenchmark kernel (Test 1).
///
/// `dd::DdKernel<W>::run(extendedprice, discount)` produces W *distinct scalar*
/// int64 SSA locals that are each data-dependent on the per-tuple input columns
/// and all of which are reduced (summed) into a single returned int64. The W
/// locals are generated by recursive template / `if constexpr`-free integer
/// sequence unrolling -- no `std::array`, no runtime loop whose bound is W -- so
/// W is a *compile-time* constant and the machine code is straight-line
/// register-pressure.
namespace dd {

/// W-index-dependent distinct constant so neighbouring intermediate values can
/// neither be CSE'd together nor constant-folded away.
constexpr int64_t ddConstant(int k) {
   return 0x9E3779B97F4A7C15LL * (int64_t)(k + 1) +
          0x51ED270BLL * (int64_t)k + 0x2545F4914F6CDD1DLL;
}

template <int W>
struct DdKernel {
   /// Compile-time intermediate k (distinct scalar SSA local). Data-dependent
   /// on both columns: `ep * Ck + (ep ^ (disc + k))`.
   template <int k>
   static inline int64_t gen(int64_t extendedprice, int64_t discount) {
      return extendedprice * ddConstant(k) + (extendedprice ^ (discount + k));
   }

   template <int... ks>
   static inline int64_t sumAll(int64_t extendedprice, int64_t discount,
                                std::integer_sequence<int, ks...>) {
      // straight-line fold over all W locals: nothing can be dead-code
      // eliminated because every local feeds this reduction.
      return (gen<ks>(extendedprice, discount) + ...);
   }

   static inline int64_t run(int64_t extendedprice, int64_t discount) {
      return sumAll(extendedprice, discount,
                    std::make_integer_sequence<int, W>{});
   }
};

}  // namespace dd
